/**
 * Content migrated verbatim from the old .NET site (EtruscaCleanArchitecture.Web,
 * Controllers/CursoController.cs + Views/Curso/*.cshtml). SEO fields are the exact
 * ViewBag.Title / Description / Keywords of each action; og:image = ViewBag.Image
 * (img/CURSOS-TALLERES-LOGO.webp, copied to /assets/images/educacion/legacy/).
 * `legacyPrice` was hidden (display:none) on the old site and is NOT rendered.
 * TODO(Héctor): confirm prices/durations — several differ from education.data.ts.
 * GENERATED by the migration script; hand edits are fine from here on.
 */
/** p: html · ul: items · img: src/alt · cta: label + href (or courseSlug → modern course page). */
export interface LegacyBlock {
  type: 'p' | 'ul' | 'img' | 'cta';
  html?: string;
  items?: ReadonlyArray<{ html: string; sub?: ReadonlyArray<string> }>;
  src?: string;
  alt?: string;
  label?: string;
  href?: string;
  courseSlug?: string;
}

export interface LegacySection {
  heading: string;
  level: number;
  blocks: ReadonlyArray<LegacyBlock>;
  /** Old "Calendario"/"Fechas disponibles" block: rendered with live dates from the events API. */
  calendar?: boolean;
  /** Added by the migration (the old view had no calendar heading). */
  added?: boolean;
  /** Image + short text + link (old card grid). */
  card?: boolean;
}

export interface LegacyCoursePage {
  /** Path without leading slash (same as the old site). */
  path: string;
  title: string;
  description: string;
  keywords: string;
  image: string;
  /** ViewBag.Theme of the old page. */
  accent: string;
  /** Equivalent course in education.data.ts (fallback for dates, JSON-LD level). */
  courseSlug?: string;
  /** categoryId the old page queried in /api/Event (none = all courses, like /curso-de-cafe). */
  categoryId?: number;
  /** locationId the old per-city page queried in /api/Event (= /api/Location id). */
  locationId?: number;
  /** City of the old page: default sucursal of the calendar when there is no locationId. */
  city?: string;
  kicker?: string;
  h1: string;
  subtitle?: string;
  icon?: string;
  meta?: ReadonlyArray<{ icon: string; label: string }>;
  sections: ReadonlyArray<LegacySection>;
  legacyPrice?: { amount: string; note: string };
}

